import{_ as a,c as t,o as r,a5 as o}from"./chunks/framework.p2RKkOSy.js";const u=JSON.parse('{"title":"Privacy","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"faq/privacy.md","filePath":"faq/privacy.md"}'),i={name:"faq/privacy.md"};function n(s,e,c,l,h,p){return r(),t("div",{"data-pagefind-body":!0},e[0]||(e[0]=[o('<h1 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#what-privacy-measures-are-in-place">What privacy measures are in place? ​</a></li><li><a href="#if-someone-finds-the-tracker-can-they-trace-it-back-to-me">If someone finds the tracker can they trace it back to me? ​</a></li></ul></nav><h2 id="what-privacy-measures-are-in-place" tabindex="-1">What privacy measures are in place? <a class="header-anchor" href="#what-privacy-measures-are-in-place" aria-label="Permalink to &quot;What privacy measures are in place?&quot;">​</a></h2><p>All data is encrypted in transit: from the moment a signal is transmitted by the device to the moment you view it.</p><p>We also adhere to all EU General Data Protection Regulation (GDPR).</p><p>Your data cannot be viewed by anyone else and we will never look at your data (unless you ask us to for support).</p><p>Your data will never be sold or used for any purpose other than providing the service you signed up for.</p><p>Please <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact us</a> if you have any questions about privacy.</p><h2 id="if-someone-finds-the-tracker-can-they-trace-it-back-to-me" tabindex="-1">If someone finds the tracker can they trace it back to me? <a class="header-anchor" href="#if-someone-finds-the-tracker-can-they-trace-it-back-to-me" aria-label="Permalink to &quot;If someone finds the tracker can they trace it back to me?&quot;">​</a></h2><p>If your tracker falls into the wrong hands there is no way they can find out who owns it.</p><p>Similarly there is no way they can re-purpose the tracker and use it for themselves or view historical data.</p><p>Please note that our devices are designed to allow you to track your own property and that in many countries it is illegal to track someone else or their property without explicit consent.</p><p>Please refer to local regulations before using LightBug devices.</p><p>We will co-operate with authorities and where illegal use has been identified, provide evidence which may be used for prosecution.</p>',14)]))}const f=a(i,[["render",n]]);export{u as __pageData,f as default};
